import java.util.*;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.inventory.*;import net.minecraft.world.entity.player.*;import dev.zomboid.remains.expand.*;
public class Checks {
 static int n;static void check(boolean b){if(!b)throw new AssertionError(n);n++;}static ItemStack stack(String tag,int count){return new ItemStack(tag,count,64);}public static class Data{public int dirty;public void setDirty(){dirty++;}}public static class Body{public SimpleContainer inventory;Body(SimpleContainer c){inventory=c;}}public static class Tag{Map<String,Integer> integers=new HashMap<>();public ListTag entries=new ListTag();public int getInt(String k){return integers.getOrDefault(k,0);}public void putInt(String k,int v){integers.put(k,v);}public ListTag getList(String k,int type){return entries;}}public static class ListTag{public List<Tag> tags=new ArrayList<>();public int size(){return tags.size();}public Tag getCompound(int i){return tags.get(i);}}
 public static void main(String[]args){Data data=new Data();SimpleContainer original=new SimpleContainer(27);for(int i=0;i<27;i++)original.setItem(i,stack("loot"+i,64));Body body=new Body(original);ExpandedBodies.install(body,data);ExpandedStorage storage=(ExpandedStorage)body.inventory;check(storage.getContainerSize()==27);ItemStack incoming=stack("new:nbt",20);storage.absorb(incoming);check(incoming.isEmpty());check(storage.getContainerSize()==36);check(storage.getItem(27).tag.equals("new:nbt"));check(storage.getItem(27).getCount()==20);check(original.getItem(0).getCount()==64);ItemStack same=stack("new:nbt",10);storage.absorb(same);check(storage.getContainerSize()==36);check(storage.getItem(27).getCount()==30);check(data.dirty>0);ItemStack different=stack("new:other",10);storage.absorb(different);check(storage.getItem(28).tag.equals("new:other"));check(storage.getContainerSize()==36);for(int i=29;i<36;i++)storage.setItem(i,stack("full"+i,64));storage.setItem(27,stack("new:nbt",64));storage.setItem(28,stack("new:other",64));ItemStack more=stack("another",150);storage.absorb(more);check(storage.getContainerSize()==45);check(storage.getItem(36).getCount()==64&&storage.getItem(38).getCount()==22);check(more.isEmpty());Tag tag=new Tag();ExpandedBodies.saveSize(body,tag);check(tag.getInt("ZGCapacity")==45);Body loaded=new Body(new SimpleContainer(27));ExpandedBodies.install(loaded,data);ExpandedBodies.restore(loaded,tag);check(loaded.inventory.getContainerSize()==45);Tag old=new Tag();Tag entry=new Tag();entry.putInt("Slot",70);old.entries.tags.add(entry);ExpandedBodies.restore(loaded,old);check(loaded.inventory.getContainerSize()==72);loaded.inventory.setItem(70,stack("preserved",4));check(loaded.inventory.getItem(70).tag.equals("preserved"));Tag saved=new Tag();ExpandedBodies.saveSize(loaded,saved);check(saved.getInt("ZGCapacity")==72);ItemStack removed=loaded.inventory.removeItem(70,2);check(removed.getCount()==2&&loaded.inventory.getItem(70).getCount()==2);loaded.inventory.clearContent();check(loaded.inventory.isEmpty()&&loaded.inventory.getContainerSize()==72);Body normal=new Body(new SimpleContainer(27));ExpandedBodies.install(normal,data);ChestMenu nativeMenu=(ChestMenu)ExpandedBodies.menu(normal,null,null,null,1,new Inventory(),new Player());check(nativeMenu.rows==3);ExpandedStorage large=new ExpandedStorage(new SimpleContainer(63),data);large.setItem(50,stack("page-two",7));PagedView view=new PagedView(large);check(view.pages()==2);check(view.getItem(49).name!=null);view.move(1);check(view.getItem(5).tag.equals("page-two"));check(view.removeItem(5,2).getCount()==2&&large.getItem(50).getCount()==5);view.move(50);check(view.getItem(5).getCount()==5);view.move(-50);check(view.getItem(5).isEmpty());view.setItem(45,stack("forged-arrow",64));check(large.getItem(45).isEmpty());PagedMenu menu=new PagedMenu(1,new Inventory(),large,null,null,null,null);for(int i=45;i<54;i++)check(!menu.slots.get(i).mayPlace(stack("x",1))&&!menu.slots.get(i).mayPickup(new Player()));menu.clicked(53,0,ClickType.PICKUP,new Player());check(menu.clicks==0);check(menu.quickMoveStack(new Player(),53).isEmpty());menu.clicked(45,0,ClickType.QUICK_MOVE,new Player());check(menu.clicks==0);menu.clicked(0,0,ClickType.PICKUP,new Player());check(menu.clicks==1);System.out.println("Expansion, persistence and paging checks: "+n);}
}
